-- Linh Nguyen is the original buff counter, not bag cargo.
EBOriginalItemMenu=EBItem
EBOriginalResultText=EBResultText
function EBItem(id,parent)
 if id~=16226 then return EBOriginalItemMenu(id,parent) end
 EBShow("Linh NguyÖn ®­îc céng trùc tiÕp vµo « buff. Tèi ®a 30, chØ dµnh cho nh©n vËt ch­a tõng nhËn nu«i linh thó.",{
 "NhËn 1/EBGive("..id..",1,"..parent..")",
 "NhËn 10/EBGive("..id..",10,"..parent..")",
 "NhËn 30/EBGive("..id..",30,"..parent..")",
 EBLabels[3].."/EBMenu("..parent..",1)"})
end
function EBResultText(result)
 if result==-8 then return "Kh«ng thÓ nhËn Linh NguyÖn: ®· ®ñ 30, ®· tõng nhËn nu«i linh thó hoÆc ch­a cã « buff trèng." end
 return EBOriginalResultText(result)
end

