function EBQuestList(common,page)
 local list={};local profession=GetPlayerType();if profession==3 then profession=0 end
 for i=1,getn(EBQuests) do
  local q=EBQuests[i]
  if (common==1 and q[1]==-1) or (common==0 and q[1]==profession) then tinsert(list,i) end
 end
 local options={};local first=(page-1)*7+1;local last=min(first+6,getn(list))
 for n=first,last do
  local id=list[n];local title=EBQuests[id][2]
  if EventHandbookAction(8,id)==2 then title="<color=green>"..title.." (®· xong)<color>" end
  tinsert(options,title.."/EBQuestSelect("..id..","..common..","..page..")")
 end
 if page>1 then tinsert(options,EBLabels[1].."/EBQuestList("..common..","..(page-1)..")") end
 if last<getn(list) then tinsert(options,EBLabels[2].."/EBQuestList("..common..","..(page+1)..")") end
 tinsert(options,EBLabels[3].."/EBQuestRoot");EBShow("danh s\184ch nhi\214m v\244",options)
end
