 "ho\181n th\181nh nhanh".."/EBQuestDo(9,"..id..","..common..","..page..")",
 "c\202p v\203t ph\200m \174\211 tr\182 nhi\214m v\244".."/EBQuestDo(10,"..id..","..common..","..page..")",
 EBLabels[3].."/EBQuestList("..common..","..page..")"})
end
function EBQuestDo(op,id,common,page)
 local result=EventHandbookAction(op,id)
 EBShow(EBResultText(result),{EBLabels[3].."/EBQuestList("..common..","..page..")"})
